{
  "table": {
    "name": "postLinks (post-to-post relationship table)",
    "purpose": "Each row records one directed link between two posts in a Stack Exchange-style Q&A database (companion tables: posts, users, votes, comments, badges, tags, postHistory). PostId is the post the link is attached to, RelatedPostId is the post it points to, and LinkTypeId classifies the relationship as an ordinary 'linked/related' association (1) or a duplicate-question relationship (3). This is the PostLinks table of the standard Stack Exchange data dump."
  },
  "columns": {
    "CreationDate": {
      "role": "date",
      "name": "Link creation timestamp",
      "description": "Timestamp (stored as text, 'YYYY-MM-DD HH:MM:SS') of when the link record was created; never null; spans 2010-07-21 to 2014-09-13, matching the site's activity period. ~85% of values are distinct; the modal value 2013-02-18 03:03:17 occurs 234 times, indicating a bulk backfill/import of links at that moment rather than organic activity. Not used as a join key.",
      "status": "resolved"
    },
    "Id": {
      "role": "identifier",
      "name": "Post link ID (surrogate primary key)",
      "description": "Unique BIGINT identifying the link row; 11,102 distinct values equal the row count and it is detected as the table's primary key. Values are sparse up to ~3.36M, consistent with a site-wide ID sequence shared across the dump. No other table joins to it.",
      "status": "resolved"
    },
    "LinkTypeId": {
      "role": "code",
      "name": "Link type code (1 = Linked, 3 = Duplicate)",
      "description": "Two-valued code distinguishing the kind of post relationship: 1 (10,186 rows, ~92%) and 3 (916 rows, ~8%). In the Stack Exchange schema this is the PostLinkType enum: 1 = Linked (the posts are related, typically auto-created when one post references the other) and 3 = Duplicate (PostId was closed as a duplicate of RelatedPostId). The observed distribution fits: duplicate links are far rarer than ordinary reference links. It is a code, not a foreign key; the accepted joins to badges.Id / comments.Id / postHistory.Id are statistical coincidences of small integers matching unrelated ID ranges.",
      "status": "resolved"
    },
    "PostId": {
      "role": "foreign_key",
      "name": "Source post ID (FK to posts.Id)",
      "description": "ID of the post the link belongs to: the post that references the related post, or the question marked as a duplicate of it. Joins to posts.Id (many-to-one). 7,604 distinct values over 11,102 rows, so a post can carry several links (multiple references, or links in both directions). Value range 4-115,360 matches posts.Id.",
      "status": "resolved"
    },
    "RelatedPostId": {
      "role": "foreign_key",
      "name": "Target (related) post ID (FK to posts.Id)",
      "description": "ID of the post being linked to: the referenced post, or the original question in a duplicate relationship. Joins to posts.Id (many-to-one). 5,177 distinct values; the most frequent targets (post 2492 with 96 inbound links, post 20836 with 93) look like canonical questions that many posts point to, supporting the reading that this is the link target. Range 1-115,163 matches posts.Id.",
      "status": "resolved"
    }
  }
}
